 "<span style=\"font-family:'JetBrains Mono', monospace;font-size:30px;color:#ffb347\">343 m/s</span><br>Aire": "<span style=\"font-family:'JetBrains Mono', monospace;font-size:30px;color:#ffb347\">343 m/s</span><br>Aire",
